from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
old='<section id="view-overview" class="view"><div class="page-head"><div><div class="eyebrow">ÜBERSICHT</div><h1>Übersicht</h1><p>Aktuelle Kennzahlen zur Personalplanung.</p></div></div><div class="stats" id="overviewStats"></div></section>'
new='''<section id="view-overview" class="view"><div class="page-head"><div><div class="eyebrow">ÜBERSICHT</div><h1>Planungs-Dashboard</h1><p>Besetzung, Personal und Handlungsbedarf der aktuellen Woche auf einen Blick.</p></div><button class="primary" onclick="showView(\'schedule\')">Dienstplan öffnen</button></div><div class="stats" id="overviewStats"></div><div class="panel-grid overview-grid" style="margin-top:14px"><div class="card table-card"><div class="table-head"><h3>Handlungsbedarf</h3><span class="badge" id="overviewIssueCount">0</span></div><div id="overviewIssues"></div></div><div class="card table-card"><div class="table-head"><h3>Abwesenheiten diese Woche</h3></div><div id="overviewAbsences"></div></div></div><div class="panel-grid overview-grid" style="margin-top:14px"><div class="card table-card"><div class="table-head"><h3>Mitarbeiter-Auslastung</h3></div><div id="overviewWorkload"></div></div><div class="card table-card"><div class="table-head"><h3>Schichtverteilung</h3></div><div id="overviewShiftMix"></div></div></div><div class="card table-card" style="margin-top:14px"><div class="table-head"><h3>Schnellaktionen</h3></div><div class="form-actions"><button class="primary" onclick="showView(\'schedule\')">▣ Dienstplan öffnen</button><button class="ghost" onclick="showView(\'employees\');document.getElementById(\'addEmployeeBtn\').click()">＋ Mitarbeiter anlegen</button><button class="ghost" onclick="showView(\'absence\')">☼ Abwesenheit eintragen</button><button class="ghost" onclick="showView(\'auto\')">✦ Auto-Planung</button></div></div></section>'''
if old not in s: raise SystemExit('overview section not found')
s=s.replace(old,new,1)
anchor='function renderEmployees(){'
fn=r'''function renderOverview(){const ds=currentWeekDates(),dates=ds.map(iso),weekA=assignments.filter(a=>dates.includes(a.date)),active=employees.filter(e=>e.status==='active'),total=dates.reduce((sum,d)=>sum+TYPES.reduce((x,t)=>x+getSoll(d,t.id),0),0),open=dates.reduce((sum,d)=>sum+TYPES.reduce((x,t)=>x+Math.max(0,getSoll(d,t.id)-assignmentsFor(d,t.id).length),0),0),filled=total-open,coverage=total?Math.round(filled/total*100):100,weekAbs=absences.filter(a=>dates.includes(a.date)),todayIso=new Date().toISOString().slice(0,10),todayA=assignments.filter(a=>a.date===todayIso);document.getElementById('overviewStats').innerHTML=`<div class="stat"><div class="stat-icon">◉</div><div><small>Planungsfortschritt</small><strong>${coverage}%</strong><em>${filled} von ${total} Positionen</em></div></div><div class="stat"><div class="stat-icon">△</div><div><small>Offene Positionen</small><strong>${open}</strong><em>${open?'Handlungsbedarf':'Woche vollständig'}</em></div></div><div class="stat"><div class="stat-icon">♧</div><div><small>Heute im Dienst</small><strong>${new Set(todayA.map(a=>a.employeeId)).size}</strong><em>${todayA.length} Schichtzuweisungen</em></div></div><div class="stat"><div class="stat-icon">☼</div><div><small>Abwesenheiten</small><strong>${weekAbs.length}</strong><em>${new Set(weekAbs.map(a=>a.employeeId)).size} Mitarbeiter betroffen</em></div></div><div class="stat"><div class="stat-icon">▣</div><div><small>Geplante Schichten</small><strong>${weekA.length}</strong><em>diese Woche</em></div></div><div class="stat"><div class="stat-icon">♧</div><div><small>Aktive Mitarbeiter</small><strong>${active.length}</strong><em>${active.length-new Set(weekAbs.map(a=>a.employeeId)).size} ohne Abwesenheit</em></div></div>`;let issues=[];dates.forEach((d,di)=>TYPES.forEach(t=>{const so=getSoll(d,t.id),is=assignmentsFor(d,t.id).length;if(is<so)issues.push({d,di,type:t.id,so,is,missing:so-is})}));issues.sort((a,b)=>b.missing-a.missing);document.getElementById('overviewIssueCount').textContent=issues.length;document.getElementById('overviewIssues').innerHTML=issues.length?issues.slice(0,10).map(x=>`<div class="section-box" style="margin-bottom:8px;display:flex;justify-content:space-between;align-items:center"><div><b>${DAYS[x.di]} ${new Date(x.d+'T00:00:00').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})} · ${x.type}</b><small style="display:block;color:var(--muted)">SOLL ${x.so} · IST ${x.is}</small></div><span class="status inactive">${x.missing} offen</span></div>`).join(''):'<div class="notice">✓ Alle benötigten Positionen dieser Woche sind besetzt.</div>';document.getElementById('overviewAbsences').innerHTML=weekAbs.length?weekAbs.sort((a,b)=>a.date.localeCompare(b.date)).map(a=>{const e=employees.find(x=>x.id===a.employeeId);return `<div class="section-box" style="margin-bottom:8px"><b>${e?e.first+' '+e.last:'Mitarbeiter'}</b><small style="display:block;color:var(--muted)">${a.type} · ${new Date(a.date+'T00:00:00').toLocaleDateString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit'})}</small></div>`}).join(''):'<div class="notice">✓ Keine Abwesenheiten in dieser Woche.</div>';const workload=active.map(e=>({e,h:plannedHoursForEmployee(e.id),target:Number(e.weeklyHours)||0})).sort((a,b)=>b.h-a.h);document.getElementById('overviewWorkload').innerHTML=workload.slice(0,10).map(x=>{const pct=x.target?Math.round(x.h/x.target*100):0;return `<div class="section-box" style="margin-bottom:8px"><div style="display:flex;justify-content:space-between"><b>${x.e.first} ${x.e.last}</b><span>${x.h.toFixed(1)} / ${x.target} Std.</span></div><small style="color:${pct>100?'var(--red)':pct>=80?'var(--amber)':'var(--muted)'}">${pct}% Wochen-SOLL</small></div>`}).join('')||'<div class="empty">Keine aktiven Mitarbeiter.</div>';document.getElementById('overviewShiftMix').innerHTML=TYPES.map(t=>{const n=weekA.filter(a=>a.type===t.id).length;return `<div class="section-box" style="margin-bottom:8px;display:flex;justify-content:space-between"><b>${t.id}</b><span>${n} Zuweisungen</span></div>`}).join('')}
'''
if anchor not in s: raise SystemExit('renderEmployees anchor not found')
s=s.replace(anchor,fn+anchor,1)
# make overview refresh when opened; locate nav click handler fragment
old2="if(v==='overview')renderOverviewStats();"
if old2 in s:s=s.replace(old2,"if(v==='overview')renderOverview();",1)
else:
    # append compatibility wrapper so any existing renderOverviewStats call gets full dashboard
    s=s.replace('</script>',"\nfunction renderOverviewStats(){renderOverview()}\n</script>",1)
p.write_text(s,encoding='utf-8')
print('Übersicht Dashboard ergänzt')
